'use client';

import { FormEvent, useCallback, useEffect, useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { API_URL } from '@/lib/api';

type Vendor = { id: string; name: string; email?: string; phone?: string; industryType?: string; qualificationStatus: string; isActive: boolean };
export default function VendorsPage() {
  const [vendors, setVendors] = useState<Vendor[]>([]); const [form, setForm] = useState({ name: '', email: '', industryType: '' }); const [error, setError] = useState('');
  const [selected, setSelected] = useState<Vendor | null>(null); const [editing, setEditing] = useState(false); const [draft, setDraft] = useState<Vendor | null>(null); const [confirmDelete, setConfirmDelete] = useState(false);
  const router = useRouter();
  const token = () => localStorage.getItem('token') || '';
  const load = useCallback(async () => { const t = localStorage.getItem('token'); if (!t) return router.push('/login'); const response = await fetch(`${API_URL}/api/vendors`, { headers: { Authorization: `Bearer ${t}` } }); if (response.status === 401 || response.status === 403) return router.push('/login'); const body = await response.json(); setVendors(body.data || []); }, [router]);
  useEffect(() => { void load(); }, [load]);
  async function create(event: FormEvent) { event.preventDefault(); setError(''); const response = await fetch(`${API_URL}/api/vendors`, { method: 'POST', headers: { Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); const body = await response.json(); if (!response.ok) return setError(body.message || 'Unable to create vendor'); setForm({ name: '', email: '', industryType: '' }); await load(); }
  function openDetails(vendor: Vendor) { setSelected(vendor); setDraft({ ...vendor }); setEditing(false); setConfirmDelete(false); setError(''); }
  function closeDetails() { setSelected(null); setEditing(false); setConfirmDelete(false); }
  async function saveEdit() {
    if (!selected || !draft) return; setError('');
    const response = await fetch(`${API_URL}/api/vendors/${selected.id}`, { method: 'PUT', headers: { Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ name: draft.name, email: draft.email, phone: draft.phone, industryType: draft.industryType, qualificationStatus: draft.qualificationStatus, isActive: draft.isActive }) });
    if (!response.ok) { const body = await response.json().catch(() => ({})); return setError(body.message || 'Unable to update vendor'); }
    closeDetails(); await load();
  }
  async function removeVendor() {
    if (!selected) return; setError('');
    const response = await fetch(`${API_URL}/api/vendors/${selected.id}`, { method: 'DELETE', headers: { Authorization: `Bearer ${token()}` } });
    if (!response.ok && response.status !== 204) { const body = await response.json().catch(() => ({})); return setError(body.message || 'Unable to delete vendor'); }
    closeDetails(); await load();
  }
  return <main className="max-w-5xl mx-auto p-8 space-y-8"><header className="flex justify-between"><div><h1 className="text-3xl font-bold">Tenant vendors</h1><p className="text-gray-600">Only vendors owned by your organization are visible.</p></div><Link href="/bids" className="text-indigo-700">Manage bids</Link></header>
    <form onSubmit={create} className="grid md:grid-cols-4 gap-3 bg-white shadow rounded p-4"><input required placeholder="Vendor name" value={form.name} onChange={e => setForm({...form,name:e.target.value})} className="border rounded px-3 py-2"/><input type="email" placeholder="Email" value={form.email} onChange={e => setForm({...form,email:e.target.value})} className="border rounded px-3 py-2"/><input placeholder="Industry" value={form.industryType} onChange={e => setForm({...form,industryType:e.target.value})} className="border rounded px-3 py-2"/><button className="bg-indigo-600 text-white rounded">Add vendor</button>{error && !selected && <p role="alert" className="md:col-span-4 text-red-700">{error}</p>}</form>
    <div className="bg-white shadow rounded divide-y">{vendors.map(v => <article key={v.id} onClick={() => openDetails(v)} tabIndex={0} role="button" aria-label={`Open details for ${v.name}`} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openDetails(v); } }} className="p-4 flex justify-between cursor-pointer hover:bg-gray-50 focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500"><div><h2 className="font-semibold">{v.name}</h2><p className="text-sm text-gray-600">{v.email || 'No email'} · {v.industryType || 'Uncategorized'}</p></div><span>{v.qualificationStatus}</span></article>)}{!vendors.length && <p className="p-6 text-gray-600">No vendors yet.</p>}</div>
    {selected && <div className="fixed inset-0 z-50 bg-gray-800/60 p-4 grid place-items-center" onMouseDown={e => e.target === e.currentTarget && closeDetails()}><section role="dialog" aria-modal="true" aria-label={`Vendor ${selected.name}`} className="bg-white rounded-lg shadow-xl w-full max-w-lg max-h-[90vh] overflow-auto"><header className="p-4 border-b flex justify-between items-center"><h2 className="text-xl font-semibold">{editing && draft ? 'Edit vendor' : selected.name}</h2><button aria-label="Close" onClick={closeDetails} className="text-gray-500">✕</button></header><div className="p-6 space-y-3">{error && <p role="alert" className="text-red-700">{error}</p>}{editing && draft ? <div className="grid gap-3"><label className="text-sm">Name<input className="border rounded px-3 py-2 w-full" value={draft.name} onChange={e => setDraft({ ...draft, name: e.target.value })}/></label><label className="text-sm">Email<input className="border rounded px-3 py-2 w-full" value={draft.email || ''} onChange={e => setDraft({ ...draft, email: e.target.value })}/></label><label className="text-sm">Phone<input className="border rounded px-3 py-2 w-full" value={draft.phone || ''} onChange={e => setDraft({ ...draft, phone: e.target.value })}/></label><label className="text-sm">Industry<input className="border rounded px-3 py-2 w-full" value={draft.industryType || ''} onChange={e => setDraft({ ...draft, industryType: e.target.value })}/></label><label className="text-sm">Qualification status<input className="border rounded px-3 py-2 w-full" value={draft.qualificationStatus} onChange={e => setDraft({ ...draft, qualificationStatus: e.target.value })}/></label><label className="text-sm flex items-center gap-2"><input type="checkbox" checked={draft.isActive} onChange={e => setDraft({ ...draft, isActive: e.target.checked })}/>Active</label></div> : <dl className="grid gap-2"><div><dt className="text-xs uppercase text-gray-500">Name</dt><dd>{selected.name}</dd></div><div><dt className="text-xs uppercase text-gray-500">Email</dt><dd>{selected.email || '—'}</dd></div><div><dt className="text-xs uppercase text-gray-500">Phone</dt><dd>{selected.phone || '—'}</dd></div><div><dt className="text-xs uppercase text-gray-500">Industry</dt><dd>{selected.industryType || '—'}</dd></div><div><dt className="text-xs uppercase text-gray-500">Qualification</dt><dd>{selected.qualificationStatus}</dd></div><div><dt className="text-xs uppercase text-gray-500">Active</dt><dd>{selected.isActive ? 'Yes' : 'No'}</dd></div></dl>}{confirmDelete && <div role="alert" className="rounded border border-red-200 bg-red-50 p-3"><strong>Delete {selected.name}?</strong><p className="text-sm text-red-800">This cannot be undone.</p><div className="mt-2 flex gap-2"><button className="bg-red-600 text-white rounded px-3 py-1" onClick={removeVendor}>Delete vendor</button><button className="border rounded px-3 py-1" onClick={() => setConfirmDelete(false)}>Cancel deletion</button></div></div>}</div><footer className="p-4 border-t flex justify-end gap-2">{editing ? <><button className="border rounded px-3 py-1" onClick={() => { setDraft({ ...selected }); setEditing(false); setConfirmDelete(false); }}>Cancel</button><button className="bg-indigo-600 text-white rounded px-3 py-1" onClick={saveEdit}>Save changes</button></> : <><button className="border rounded px-3 py-1" onClick={closeDetails}>Cancel</button><button className="border rounded px-3 py-1" onClick={() => { setDraft({ ...selected }); setEditing(true); setConfirmDelete(false); }}>Edit</button><button className="border border-red-300 text-red-700 rounded px-3 py-1" onClick={() => setConfirmDelete(true)}>Delete</button></>}</footer></section></div>}
  </main>;
}
